// 解析阿里云云效 API 返回的 MR 数据
const mrs = $input.item.json || [];

// 获取配置信息，传递到后续节点
const config = {
  ALIYUN_ORGANIZATION_ID: $('⚙️ 配置中心 (请修改这里)').item.json.ALIYUN_ORGANIZATION_ID,
  ALIYUN_REPO_ID: $('⚙️ 配置中心 (请修改这里)').item.json.ALIYUN_REPO_ID,
  FEISHU_APP_TOKEN: $('⚙️ 配置中心 (请修改这里)').item.json.FEISHU_APP_TOKEN,
  FEISHU_TABLE_ID: $('⚙️ 配置中心 (请修改这里)').item.json.FEISHU_TABLE_ID
};

// 如果返回的是数组，直接使用；否则检查是否在某个字段中
let mrList = [];
if (Array.isArray(mrs)) {
  mrList = mrs;
} else if (mrs.data && Array.isArray(mrs.data)) {
  mrList = mrs.data;
} else if (mrs.result && Array.isArray(mrs.result)) {
  mrList = mrs.result;
}

if (mrList.length === 0) {
  return [];
}

// 为每个 MR 创建一个输出项，同时携带配置信息
return mrList.map(mr => ({
  json: {
    mr_id: mr.iid || mr.id,
    mr_title: mr.title,
    mr_description: mr.description || '',
    mr_author: mr.author?.name || mr.author?.username || 'Unknown',
    mr_author_email: mr.author?.email || '',
    mr_source_branch: mr.source_branch,
    mr_target_branch: mr.target_branch,
    mr_created_date: mr.created_at,
    mr_updated_date: mr.updated_at,
    mr_link: mr.web_url,
    mr_project_id: mr.project_id || config.ALIYUN_REPO_ID,
    _config: config
  }
}));

// 准备发送给千问的 prompt
const mrData = $input.item.json;
const changesData = mrData.data || mrData;

// 构建 diff 内容
let diffContent = '';
if (changesData.changes && Array.isArray(changesData.changes)) {
  changesData.changes.forEach(change => {
    diffContent += `\n=== ${change.old_path || change.new_path} ===\n`;
    diffContent += change.diff || '';
  });
} else if (changesData.diffs && Array.isArray(changesData.diffs)) {
  changesData.diffs.forEach(diff => {
    diffContent += `\n=== ${diff.oldPath || diff.newPath} ===\n`;
    diffContent += diff.diff || '';
  });
}

// 如果 diff 为空，尝试从其他字段获取
if (!diffContent && changesData.diff) {
  diffContent = changesData.diff;
}

// 限制 diff 内容长度，避免 token 过多
const maxDiffLength = 8000;
const truncatedDiff = diffContent.length > maxDiffLength 
  ? diffContent.substring(0, maxDiffLength) + '\n... (内容已截断)'
  : diffContent;

const prompt = `你是一个资深的代码审查专家。请对以下 Merge Request 进行全面评估：

**MR 信息：**
- 标题：${mrData.mr_title}
- 描述：${mrData.mr_description}
- 作者：${mrData.mr_author}
- 源分支：${mrData.mr_source_branch}
- 目标分支：${mrData.mr_target_branch}

**代码变更（Diff）：**
\`\`\`diff
${truncatedDiff}
\`\`\`

请从以下维度进行评估：
1. **代码缺陷**：是否存在逻辑错误、边界条件问题、空指针等
2. **注释程度**：代码注释是否充分、清晰
3. **合理性**：代码设计是否合理、是否遵循最佳实践
4. **安全性**：是否存在安全漏洞、敏感信息泄露等

请按照以下 JSON 格式返回评估结果：
{
  "issues": [
    {
      "level": "高|中|低",
      "category": "代码缺陷|注释程度|合理性|安全性",
      "description": "问题描述",
      "location": "代码位置或文件名",
      "suggestion": "改进建议"
    }
  ],
  "overall_score": "0-100 分",
  "summary": "总体评价"
}`;

return [{
  json: {
    ...mrData,
    diff_content: truncatedDiff,
    ai_prompt: prompt
  }
}];

