// 解析千问返回的结果并进行分类
const item = $input.item.json;
const mrData = item;

// 提取 AI 返回的内容
let aiResponse = '';
try {
  aiResponse = item.output?.choices?.[0]?.message?.content || '';
} catch (e) {
  aiResponse = '';
}

// 尝试解析 JSON 格式的 AI 响应
let evaluation = {
  issues: [],
  overall_score: 'N/A',
  summary: 'AI 未能返回有效评估'
};

try {
  // 提取 JSON 部分（可能被包裹在 markdown 代码块中）
  const jsonMatch = aiResponse.match(/```json\s*([\s\S]*?)```/) || 
                    aiResponse.match(/\{[\s\S]*\}/);

  if (jsonMatch) {
    const jsonStr = jsonMatch[1] || jsonMatch[0];
    evaluation = JSON.parse(jsonStr);
  }
} catch (e) {
  // 如果解析失败，创建一个默认的评估结果
  evaluation.summary = aiResponse.substring(0, 500);
}

// 按照高中低维度分类
const categorizedIssues = {
  high: [],
  medium: [],
  low: []
};

evaluation.issues.forEach(issue => {
  const level = issue.level.toLowerCase();
  if (level.includes('高')) {
    categorizedIssues.high.push(issue);
  } else if (level.includes('中')) {
    categorizedIssues.medium.push(issue);
  } else {
    categorizedIssues.low.push(issue);
  }
});

// 格式化输出数据
const output = {
  mr_id: mrData.mr_id,
  mr_title: mrData.mr_title,
  mr_author: mrData.mr_author,
  mr_author_email: mrData.mr_author_email,
  mr_link: mrData.mr_link,
  mr_created_date: mrData.mr_created_date,
  evaluation_date: new Date().toISOString(),
  overall_score: evaluation.overall_score,
  summary: evaluation.summary,
  high_issues_count: categorizedIssues.high.length,
  medium_issues_count: categorizedIssues.medium.length,
  low_issues_count: categorizedIssues.low.length,
  high_issues: categorizedIssues.high,
  medium_issues: categorizedIssues.medium,
  low_issues: categorizedIssues.low,
  all_issues: evaluation.issues,
  _config: mrData._config
};

return [{ json: output }];

// 为每个问题级别创建一个飞书表格行
const data = $input.item.json;
const rows = [];

// 创建高优先级问题的行
data.high_issues.forEach((issue, index) => {
  rows.push({
    json: {
      mr_id: data.mr_id,
      mr_title: data.mr_title,
      mr_author: data.mr_author,
      mr_link: data.mr_link,
      evaluation_date: data.evaluation_date,
      issue_level: '高',
      issue_category: issue.category,
      issue_description: issue.description,
      issue_location: issue.location || 'N/A',
      issue_suggestion: issue.suggestion || 'N/A',
      overall_score: data.overall_score,
      summary: index === 0 ? data.summary : '', // 只在第一行显示摘要
      _config: data._config
    }
  });
});

// 创建中优先级问题的行
data.medium_issues.forEach((issue, index) => {
  rows.push({
    json: {
      mr_id: data.mr_id,
      mr_title: data.mr_title,
      mr_author: data.mr_author,
      mr_link: data.mr_link,
      evaluation_date: data.evaluation_date,
      issue_level: '中',
      issue_category: issue.category,
      issue_description: issue.description,
      issue_location: issue.location || 'N/A',
      issue_suggestion: issue.suggestion || 'N/A',
      overall_score: data.overall_score,
      summary: (data.high_issues.length === 0 && index === 0) ? data.summary : '',
      _config: data._config
    }
  });
});

// 创建低优先级问题的行
data.low_issues.forEach((issue, index) => {
  rows.push({
    json: {
      mr_id: data.mr_id,
      mr_title: data.mr_title,
      mr_author: data.mr_author,
      mr_link: data.mr_link,
      evaluation_date: data.evaluation_date,
      issue_level: '低',
      issue_category: issue.category,
      issue_description: issue.description,
      issue_location: issue.location || 'N/A',
      issue_suggestion: issue.suggestion || 'N/A',
      overall_score: data.overall_score,
      summary: (data.high_issues.length === 0 && data.medium_issues.length === 0 && index === 0) ? data.summary : '',
      _config: data._config
    }
  });
});

// 如果没有任何问题，创建一个表示无问题的行
if (rows.length === 0) {
  rows.push({
    json: {
      mr_id: data.mr_id,
      mr_title: data.mr_title,
      mr_author: data.mr_author,
      mr_link: data.mr_link,
      evaluation_date: data.evaluation_date,
      issue_level: '无',
      issue_category: '无问题',
      issue_description: '代码审查未发现明显问题',
      issue_location: 'N/A',
      issue_suggestion: 'N/A',
      overall_score: data.overall_score,
      summary: data.summary,
      _config: data._config
    }
  });
}

return rows;

